SELECT '---source---';
SELECT source, count(*) FROM f GROUP BY 1;
SELECT '---geomtype by tier---';
SELECT tier, ST_GeometryType(geometry) gt, count(*) FROM f GROUP BY 1,2 ORDER BY 1;
SELECT '---weight stats---';
SELECT tier, min(weight), max(weight), avg(weight), count(*) filter (where weight is null) nulls FROM f GROUP BY 1;
EOF
