cat > /tmp/step1.sql <<'EOF'
INSTALL spatial; INSTALL httpfs; LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
-- input list
CREATE TABLE input_raw AS
SELECT row_number() OVER () AS rn, cod_imovel, municipio, cod_estado, geometry AS wkt
FROM read_csv('lists/goias-sample.csv', header=true, all_varchar=true);
-- listed CAR parcels (only rows whose id appears in the list)
CREATE TABLE listed_car AS
SELECT c.cod_imovel, c.municipio, c.cod_estado, c.num_area, c.geometry AS geom
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet') c
WHERE c.cod_imovel IN (SELECT DISTINCT cod_imovel FROM input_raw WHERE cod_imovel IS NOT NULL AND cod_imovel <> '');
SELECT count(*) rows_pulled, count(distinct cod_imovel) ids FROM listed_car;
EOF
timeout 900 duckdb /workspace/work.db < /tmp/step1.sql 2>&1 | tail -10

cat > /tmp/noid.sql <<'EOF'
