SET geometry_always_xy = true;
.mode box
SELECT rn, ST_GeometryType(ST_GeomFromText(wkt)) gt,
  round(ST_X(ST_Centroid(ST_GeomFromText(wkt))),4) cx,
  round(ST_Y(ST_Centroid(ST_GeomFromText(wkt))),4) cy
FROM input_raw WHERE cod_imovel IS NULL OR cod_imovel='';
EOF
