cat > /tmp/parcels.sql <<'EOF'
INSTALL spatial; INSTALL httpfs; LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE resolved_extra AS
SELECT c.cod_imovel, c.municipio, c.cod_estado, c.num_area, c.geometry AS geom
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet') c
WHERE c.cod_imovel IN (
 'GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605',
 'GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE',
 'GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448');
-- unified parcels (117)
CREATE OR REPLACE TABLE parcels AS
SELECT cod_imovel, municipio, cod_estado, num_area, geom FROM listed_car
UNION ALL
SELECT cod_imovel, municipio, cod_estado, num_area, geom FROM resolved_extra;
SELECT count(*) n, count(distinct cod_imovel) d FROM parcels;
SELECT count(*) under1 FROM parcels WHERE num_area < 1;
EOF
timeout 300 duckdb /workspace/work.db < /tmp/parcels.sql 2>&1 | tail -12

