cat > /tmp/buf.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy=true;
-- buffered union of all parcels, dissolved, back in 4326
CREATE OR REPLACE TABLE union_buf AS
SELECT ST_Transform(
         ST_Union_Agg(
           ST_Buffer(ST_Transform(geom, 'EPSG:4326','EPSG:5880'), 25.0)
         ), 'EPSG:5880','EPSG:4326') AS ug
FROM parcels;
SELECT ST_GeometryType(ug), ST_Area(ug) area_deg2 FROM union_buf;
EOF
timeout 600 duckdb /workspace/work.db < /tmp/buf.sql 2>&1 | tail -8

cat > /tmp/year.sql <<'EOF'
INSTALL spatial; INSTALL httpfs; LOAD spatial; LOAD httpfs;
SET geometry_always_xy=true;
CREATE OR REPLACE TABLE field_year AS
WITH env AS (
  SELECT min(ST_XMin(geom)) x0, min(ST_YMin(geom)) y0, max(ST_XMax(geom)) x1, max(ST_YMax(geom)) y1 FROM parcels
)
SELECT t.Id AS field_id, t.mode_year, t.firstyear, t.firstyearmajority
FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') t, env e
WHERE t.bbox.xmin <= e.x1 AND t.bbox.xmax >= e.x0 AND t.bbox.ymin <= e.y1 AND t.bbox.ymax >= e.y0
  AND t.Id IN (SELECT field_id FROM fields);
SELECT count(*) n, count(distinct field_id) d FROM field_year;
SELECT mode_year, count(*) FROM field_year GROUP BY 1 ORDER BY 1;
EOF
timeout 600 duckdb /workspace/work.db < /tmp/year.sql 2>&1 | tail -30

