cat > /tmp/cent.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy=true;
CREATE OR REPLACE TABLE parcel_centroid AS
SELECT p.cod_imovel,
  split_part(p.cod_imovel,'-',2) AS muni_code,
  ST_Transform(ST_Centroid(p.geom),'EPSG:4326','EPSG:5880') AS c5880,
  ST_Centroid(p.geom) AS c4326
FROM parcels p WHERE p.cod_imovel IN (SELECT cod_imovel FROM flagged);
-- dominant + delivery tier assignment
CREATE OR REPLACE TABLE flagged_dom AS
SELECT f.cod_imovel, f.post2020_loss_ha, d.dominant_mb, s.commodity, r.tiers AS routing_tiers
FROM flagged f JOIN dominant d USING(cod_imovel)
LEFT JOIN scope s ON d.dominant_mb=s.mbmode24
LEFT JOIN routing r ON d.dominant_mb=r.mbmode24;
.mode box
SELECT cod_imovel, dominant_mb, commodity, routing_tiers FROM flagged_dom ORDER BY commodity;
SELECT count(*) FROM parcel_centroid;
EOF
duckdb /workspace/work.db < /tmp/cent.sql 2>&1 | tail -24

cat > /tmp/near.sql <<'EOF'
INSTALL spatial; LOAD spatial;
CREATE OR REPLACE TABLE nearest_delivery AS
SELECT cod_imovel, tier, entity_id, entity_kind, weight, basis, distance_km FROM (
  SELECT *, row_number() OVER (PARTITION BY cod_imovel ORDER BY distance_km ASC, entity_id ASC) rn
  FROM delivery_dist) WHERE rn=1;
.mode box
SELECT cod_imovel, tier, entity_id, entity_kind, round(distance_km,3) dkm FROM nearest_delivery ORDER BY distance_km;
EOF
